// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Differential run develop vs branch (WP9 3.11.6, Layer 3): a GRAPH variable that another pattern binds to a literal
 * must simply not match (a literal is never a graph name). On the branch the join order of the query below lets
 * {@code ?s :p ?g} bind ?g = "a" before the GRAPH pattern is evaluated, and the literal is cast to a context
 * {@code Resource} (ClassCastException MemLiteral -> Resource). Develop returns no rows.
 */
public class GraphVariableBoundToLiteralTest {

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	@Test
	public void graphVariableBoundToLiteralByUnionBranchDoesNotMatch() throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n:a :p :c .\n:c :p \"a\" .\n"), "http://ex/",
					RDFFormat.TRIG);
			String query = "PREFIX : <http://ex/>\nSELECT * WHERE { GRAPH ?g { ?y :p :c . :b :p ?s . }"
					+ " { ?s :p ?g . MINUS { } } UNION { } }";
			List<BindingSet> result = new ArrayList<>();
			try (TupleQueryResult res = conn.prepareTupleQuery(query).evaluate()) {
				res.forEach(result::add);
			}
			assertEquals(List.of(), result);
		}
	}
}
